fun List<Notification>.withDedupIndex(): List<Notification> {
    val seen = mutableMapOf<String, Int>()
    return map { item ->
        val count = seen.getOrDefault(item.id, 0)
        seen[item.id] = count + 1
        // copy() first: if the same Notification instance appears more than
        // once in the source list (aliased reference), mutating dedupIndex
        // in place would overwrite the earlier occurrence's index too,
        // since both entries would point at the same object.
        item.copy().also { it.dedupIndex = count }
    }
}

