    // rememberUpdatedState avoids a stale capture: remember(item.id) only
    // re-runs the lambda factory when item.id changes, so without this the
    // remembered lambda would keep calling the `onItemClick` from whichever
    // recomposition first created it for that id, ignoring later ones.
    val currentOnItemClick by rememberUpdatedState(onItemClick)
    val onClick = remember(item.id) { { currentOnItemClick(item) } }
    ItemRow(item, onClick = onClick)
